<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import AppShell from '../components/AppShell.vue'
import StatePanel from '../components/StatePanel.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { consoleApi } from '../api/client'
import type { IncidentSummary } from '../api/types'

const items=ref<IncidentSummary[]>([]), cursor=ref<string|null>(null), hasMore=ref(false), failed=ref(false), loading=ref(true)
const status=ref(''), severity=ref(''), search=ref(''); let debounce:number|undefined
const format=(v:string)=>new Intl.DateTimeFormat('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(v))
async function load(append=false){loading.value=true;failed.value=false;try{const {data}=await consoleApi.incidents({limit:20,cursor:append?cursor.value||undefined:undefined,status:status.value||undefined,severity:severity.value||undefined,search:search.value||undefined});items.value=append?[...items.value,...data.items]:data.items;cursor.value=data.nextCursor;hasMore.value=data.hasMore}catch{failed.value=true}finally{loading.value=false}}
watch([status,severity],()=>load());watch(search,()=>{clearTimeout(debounce);debounce=window.setTimeout(()=>load(),320)});onMounted(()=>load())
</script>
<template><AppShell section="incidents"><header><p class="eyebrow">Evidence-backed records</p><h1 class="page-title">Incidents</h1></header>
<section class="filters panel"><input v-model="search" maxlength="100" placeholder="搜索标题或告警名称" aria-label="搜索 Incident"><select v-model="status" aria-label="状态"><option value="">全部状态</option><option v-for="v in ['OPEN','DIAGNOSING','DIAGNOSED','FAILED','RESOLVED','CLOSED']" :key="v">{{v}}</option></select><select v-model="severity" aria-label="严重级别"><option value="">全部级别</option><option v-for="v in ['INFO','WARNING','CRITICAL']" :key="v">{{v}}</option></select></section>
<StatePanel v-if="failed" title="Incident 列表不可达" detail="请检查 ops-api 控制面，而不是把 API 离线误判成没有告警。" action="重试" @action="load()"/>
<section v-else class="table panel"><div class="table-head"><span>Last signal</span><span>Incident</span><span>Service</span><span>Status</span><span>Evidence</span></div><RouterLink v-for="item in items" :key="item.id" :to="{name:'casefile',params:{id:item.id}}" class="row"><time class="mono">{{format(item.lastAlertAt)}}</time><div><strong>{{item.title}}</strong><small class="mono">{{item.id}}</small></div><span>{{item.primaryService}}</span><StatusBadge :value="item.status"/><span class="mono">{{item.evidenceCount}}</span></RouterLink><div v-if="loading" class="loading">正在读取受控摘要…</div><StatePanel v-else-if="!items.length" title="没有符合条件的 Incident" detail="调整筛选条件，或等待受控告警进入。"/><button v-if="hasMore&&!loading" class="more" type="button" @click="load(true)">加载下一页</button></section>
</AppShell></template>
<style scoped>.filters{display:flex;gap:10px;padding:12px;margin-bottom:16px}.filters input,.filters select{background:var(--surface-2);border:1px solid var(--line);color:var(--text);border-radius:6px;padding:10px 12px}.filters input{flex:1}.filters select{min-width:150px}.table{overflow:hidden}.table-head,.row{display:grid;grid-template-columns:150px minmax(260px,1.5fr) minmax(120px,.7fr) 120px 70px;gap:18px;align-items:center;padding:14px 18px}.table-head{color:var(--text-muted);font-size:10px;text-transform:uppercase;letter-spacing:.08em}.row{border-top:1px solid var(--line-soft);transition:background 150ms var(--ease)}.row:hover{background:var(--surface-2)}.row time,.row small{color:var(--text-muted);font-size:10px}.row strong{display:block}.row small{display:block;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:260px}.loading{text-align:center;padding:28px;color:var(--text-muted)}.more{display:block;margin:18px auto;border:1px solid var(--line);background:var(--surface-2);color:var(--text);padding:9px 16px;border-radius:6px;cursor:pointer}@media(max-width:850px){.filters{display:grid;grid-template-columns:1fr 1fr}.filters input{grid-column:1/-1}.table-head{display:none}.row{grid-template-columns:1fr auto}.row>time,.row>span:not(.badge){display:none}}@media(max-width:480px){.filters{grid-template-columns:1fr}.filters input{grid-column:auto}.filters select{min-width:0}}</style>
